insert into public.lore_entries (slug, title, category, content, pathway, epoch, city, npcs, sequences, tags, token_count)
values
  ('bayam-cathedral-of-waves', 'Bayam — The Cathedral of Waves', 'location', 'The Cathedral of Waves is the Church of the Lord of Storms'' great seat in the Rorsted Archipelago — for now the largest cathedral in all Bayam, its bells timed to the tides and its seafront steps worn by sailors leaving offerings before a voyage. But its true weight is not in its stone. Of all the nations only Loen''s storm-faith holds authority over the sea, and in the Sonia Sea that authority runs through this cathedral: it is the diocese from which the Church administers the Beyonder world of the whole archipelago, answering to the Pontiff Gaard II at the Chasm of Storms Cathedral on distant Pasu Island. Its archbishop, Jahn Kottman — a Sea King of fearsome repute who boasts that even a War Bishop must bow his head in his waters — has long been the real ruler of the islands'' hidden world, and through him the Mandated Punishers keep their watch. From here the Church wages its quiet, endless war on the outlawed worship of the native sea-god, hauling heretics in every month or two; and from here it would answer, should the drowned thing the old cardinals are said to have driven into hiding a century ago ever stir again.', null, 5, 'bayam', ARRAY['Jahn Kottman'], '{}', ARRAY['cathedral', 'lord-of-storms', 'religion', 'bayam', 'setting'], 250),
  ('moses-ascetic-order-present-day', 'The Moses Ascetic Order — In the Present Day', 'organization', 'The Moses Ascetic Order persists as a secret order of Hermit-pathway warlocks who worship the Hidden Sage — the pathway''s knowledge come to life — as their god. Founded in the Fourth Epoch by humans who had read a Blasphemy Slate, it began as morally upright pursuers of knowledge under the maxim "Do as you wish, but do no harm," on good terms with the orthodox Churches. It curdled when that abstract ideal awoke into a real, whispering existence: the Hidden Sage now tests every Hermit-pathway Beyonder by pouring knowledge into their ears, and those who cannot assimilate it are driven to raving madness. Its members lead ascetic, silent lives to endure that pressure, and find it comparatively safe to listen — their great advantage and their leash. Cattleya, later a Pirate Queen and the Tarot Club''s Hermit, was once one of the Order''s ten Pillars; she nearly lost control to the Sage before Mr. Fool pulled her into the gray fog. Against the Order stands the Element Dawn, founded by Queen Mystic Bernadette Gustav to fight it. Its strongholds stay hidden and its members scatter among scholars and navigators, known — when at all — by knowledge no honest study could earn.', null, 5, null, ARRAY['Hidden Sage', 'Cattleya', 'Bernadette Gustav', 'Mr. Fool'], ARRAY[6], ARRAY['moses-ascetic-order', 'hermit-pathway', 'hidden-sage', 'element-dawn', 'secret-organization', 'spoiler'], 250),
  ('npc-anderson-hood', 'Anderson Hood — Strongest Hunter of the Fog Sea', 'npc', 'Anderson Hood is a renowned treasure hunter of the Fog Sea — self-styled its Strongest Hunter, though he cheerfully clarifies "strongest below a demigod" when pressed. Twenty-nine years old, medium-built, with short blond hair split seventy-thirty and emerald-green eyes, he was born in Segar and studied at the Church of the God of Knowledge and Wisdom''s schools in Lenburg alongside Edwina Edwards, until repeated failed examinations saw him driven out — a grudge he still airs freely, though he keeps his connections to the Knowledge church. He is a Beyonder of the Red Priest pathway just below the demigod tier, a former member of the Iron and Blood Cross Order, adaptive, insatiably curious, and naturally provoking even when he says nothing provocative at all. Among the sea''s pirates his reputation is poisonous: the man who smiles to your face and stabs you the moment you turn — yet somehow it is always the pirates who hunted him who end up traded in as bounty receipts. He hires onto ships as it suits him, chases abandoned temples and sunken ruins for gold and mystical items, and survives everything.', null, 5, null, ARRAY['Anderson Hood', 'Edwina Edwards'], ARRAY[7], ARRAY['red-priest-pathway', 'fog-sea', 'treasure-hunter', 'iron-and-blood-cross-order', 'spoiler'], 250),
  ('npc-arianna', 'Arianna — Head of the Evernight Goddess''s Thirteen Archbishops', 'npc', 'Arianna is the Matron of the Evernight Cloister and Head of the Thirteen Archbishops of the Church of the Evernight Goddess — by most reckonings, the likely next Pope. An ascetic who asks to be called "Ma''am" rather than "Your Eminence," she goes barefoot in a patched linen robe belted with tree bark, her manner all calm and quiet serenity, and she keeps a conscience strong enough to balk at sacrificing innocents for the Church''s ends, as she did over Belltaine City. She is a Servant of Concealment, a Sequence 2 Angel of the Darkness Pathway, and a Mythical Creature in truth, though she wears an ordinary woman''s black eyes and raven hair. Her most important tie is to Klein Moretti: sent in answer to his prayers to the Evernight Goddess, she relays and lends the Goddess''s oracles and the blessing of Concealment to him, becoming one of the Church''s surest hands through the strange events around him — from purging Amon''s avatars in Backlund to saving Belltaine. Among the Church''s upper echelon — thirteen archbishops and nine high-ranking deacons, all equal in rank and answerable only to the Goddess and the Pope — she stands as head of the archbishops.', null, 5, null, ARRAY['Arianna', 'Klein Moretti'], ARRAY[2], ARRAY['evernight-goddess', 'archbishop', 'darkness-pathway', 'cloister'], 235),
  ('npc-azik-eggers', 'Azik Eggers — The Angel of Death', 'npc', 'Azik Eggers is a mild-mannered history lecturer at Tingen University, known to the original Klein Moretti from his student days as a kind and dependable teacher. Behind that academic facade stands one of the most ancient Beyonders alive: a Sequence 2 Angel of the Death pathway bearing the title Death Consul, born in the Fourth Epoch and over thirteen centuries old. He is the son of Salinger — the being who held the Sequence 0 authority of Death — and was once a Death Consul and even Emperor of the Balam Empire, later living for a time as the first Baron of Lamud Town. Azik suffers from cyclical amnesia: at his father''s death, Salinger split Azik''s soul in two, and because the returned half is incomplete, Azik dies and resurrects roughly every sixty years, waking without memories and rediscovering his past anew. Thus the gentle professor genuinely does not recall his true nature. He has never refused to help Klein, and fragments of his power surface in life-threatening moments. He gave Klein his copper whistle, which summons a contracted skeletal death-messenger far beyond Klein''s own sequence. He is now the Angel of Death under The Fool, named in the Church of the Fool''s bible as consul of the Underworld.', 'death', 5, 'tingen', ARRAY['Azik Eggers', 'Salinger'], ARRAY[2], ARRAY['death-pathway', 'angel', 'death-consul', 'angel-of-death', 'ancient-being', 'balam-empire', 'university', 'mentor', 'amnesia'], 250),
  ('npc-bernadette-gustav', 'Bernadette Gustav — The Queen Mystic', 'npc', 'Bernadette Gustav, the Queen Mystic, is one of the great Pirate Kings of the seas and the eldest daughter of Emperor Roselle himself — born 1155, once a princess of Intis, now nearly two centuries old and sailing beyond any nation''s law aboard her ship the Dawn, with a bounty of six hundred and fifty thousand pounds on her head. She is a Beyonder of the Hermit pathway at Sequence 3, a Clairvoyant, veiled in black lace and bonnet, her chestnut hair to her waist and her dress a strange, twisted fashion no tailor of this age can place. She founded the Element Dawn, an organization built to fight the Moses Ascetic Order and its raving god, and leads resistance in West Balam against the Intis colonial authorities. Her disciple is the pirate captain Cattleya. Beneath the legend is a daughter''s long grief: she hated her father when he turned tyrant, never called him father for years, and has spent lifetimes since tracing his history, buying up his scattered diary pages, and searching for the answer to his final madness — because she has never fully believed that Roselle Gustav is dead.', null, 5, null, ARRAY['Bernadette Gustav', 'Roselle Gustav', 'Cattleya'], ARRAY[6], ARRAY['pirate-kings', 'hermit-pathway', 'element-dawn', 'queen-mystic', 'the-dawn', 'spoiler'], 265),
  ('npc-bethel-abraham', 'Bethel Abraham — Mr. Door, the Banished King of Angels', 'npc', 'Bethel Abraham — known to the few permitted the privilege as Mr. Door — is the ancestor of the Abraham Family and a King of Angels of the Door pathway, holder of all three Key of Stars characteristics and the pathway''s Uniqueness. In the Fourth Epoch he stood among the highest nobles of the Solomon and later Tudor Empires, was reckoned the Angel most likely to become a god, and helped slay Zaratul Senior in the War of the Four Emperors. But corruption from an outer power took root in him, waking a second identity inside his mind, and the Evernight Goddess and the Lord of Storms banished him beyond the world into an isolated space of storms and darkness. Ever since, his cries for help have leaked back through — heard only by his own descendants, loudest under the full Blood Moon — and those pleas have driven the Abraham Family''s strongest Beyonders mad, generation after generation. The bitter truth, known to almost no one: the sane half of Mr. Door sends a different message. "Don''t save me." He wrecks his own family''s high Sequences deliberately, so that none of them can ever learn the way to set him — and what rides him — free. Beyonders deep in the Door pathway sometimes brush against his voice at the edge of their rituals.', null, 5, null, ARRAY['Bethel Abraham', 'Fors Wall'], ARRAY[4], ARRAY['abraham-family', 'door-pathway', 'king-of-angels', 'mr-door', 'spoiler'], 285),
  ('npc-biles', 'Biles — Belltaine Veteran', 'npc', 'Biles is a former Loen soldier and a Sequence 9 Sailor of the Tyrant pathway, a survivor of the 1350 World War who fought in the defense of his hometown, Belltaine City. A tanned man not yet thirty, his labor-hardened muscles give the impression of steel. Like many soldiers who stumbled into supernatural power amid the war''s chaos, he either lost contact with his unit or quietly avoided it, and fell in with three fellow veteran Beyonders — Roy, Phil, and Pasha — bound together by shared experience. After the war the four return to Belltaine, a coal town bled dry as its mines fail and its young people leave for Constant and Backlund, hoping to find surviving friends and family. Instead they are caught in the terrifying anomalies unleashed when the Sealed Artifact 0-02, the Trunsoest Brass Book, runs wild in the city — Phil''s hand severed by an unseen force, their acquaintance Dr. Weber found hanged in midair. Biles shows real courage confronting the horror, and assists the wandering "magician" Merlin Hermes (Klein Moretti in disguise); his paradoxical status as both Belltaine native and returned outsider proves key to stopping 0-02. Afterward his memories of the artifact are mercifully sealed for his own protection.', null, 5, null, ARRAY['Biles', 'Roy', 'Phil', 'Pasha', 'Weber', 'Klein Moretti'], ARRAY[8], ARRAY['belltaine', 'tyrant-pathway', 'war-veteran', 'sealed-artifact-incident', 'spoiler'], 260),
  ('npc-bravehearts-temperance', 'Sharron & Maric — the Bravehearts Bar Exiles', 'npc', 'Sharron and Maric are two Beyonders of the Chained pathway who fled the Rose School of Thought after its Indulgence faction ambushed and shattered the Temperance faction they belonged to. Hunted for years, Sharron, Maric, and their leader Reinette Tinekerr fled in a sorry state and found shelter under the Tarot Club''s "The Fool," whose protection kept the Mother Tree of Desire from reclaiming them. In Backlund they keep to the Bravehearts Bar on Backlund Bridge and to lodgings at Garde Street in Hillston borough — Sharron a formidable, watchful bodyguard (first hired by "The Fool" himself) who will in time carry the Tarot name "Temperance," and Maric her steadfast companion, who will one day sit among the Tarot as the "Knight of Swords." Survivors of an order that turned to devouring desire, they hold instead to the discipline of restraint the Rose School abandoned, insisting they are its true orthodox branch. To ordinary Backlunders they are foreign regulars at a riverside bar; in truth they are exiles of a heresy, sheltering with the network that opposes the Mother Tree of Desire, and fiercely loyal to the patron who took them in when their own kind hunted them.', null, 5, 'backlund', ARRAY['Sharron', 'Maric', 'Reinette Tinekerr'], '{}', ARRAY['backlund', 'rose-school-of-thought', 'temperance', 'tarot-club', 'chained-pathway'], 250),
  ('npc-clarice', 'Clarice — Demoness of Black', 'npc', 'Clarice, known as the Demoness of Black, is one of the higher-ups of the Demoness Sect — a Saint, Sequence 3 Unaging of the Demoness pathway. She is often seen in a black court dress, with bright gray eyes and neatly tied black hair, and her beauty invokes an unexplainable sense of sympathy in the beholder. By her own account her mother is a descendant of the Primordial Demoness, and her blood also carries the Tamara lineage of the old Demoness families. Clarice operates out of the Intis Republic, where she manages the sect''s members in Trier, maintains contact with local collaborators, and cleans up the Mirror People. Within the sect''s colour-coded hierarchy she stands among figures such as Katarina Pelle, the Saintess of White, and takes students of her own. Her appetites run in the sect''s oldest vein: she speaks appreciatively of the taste of Hunters of the Red Priest pathway — the higher their Sequence, the more intense and brave they grow. Late in the window she is entrusted with a singular treasure — custody of the Conqueror Beyonder characteristic that the Augustus Family paid to the Demoness Sect for its help in the Great Smog of Backlund — making her the quiet keeper of one of the era''s most explosive secrets.', null, 5, null, ARRAY['Clarice', 'Katarina Pelle'], ARRAY[4], ARRAY['demoness-sect', 'saint', 'mirror-people', 'hidden-figure', 'spoiler'], 260),
  ('npc-colin-iliad', 'Colin Iliad — Chief of the City of Silver', 'npc', 'Chief Colin Iliad heads the six-member Council that rules the City of Silver. Over two point three metres tall, white-haired, his face carved with twisted old scars and deep wrinkles, he is a demigod of the Twilight Giant pathway — a Sequence 4 Demon Hunter of vast experience, one of the rare demigods in full control of his Mythical Creature form. His signature weapons are paired silver straight swords that resize to serve him in either form, hung crossed on his office wall between expeditions; his belt carries secret compartments of potions, oils, and salves he deploys with a veteran''s judgment, and his handwritten bestiary notebook trains the city''s young explorers. Colin has led the city''s great expeditions into the dark for decades and has paid the price the city''s harsh survival law demands: he has put down corrupted kin with his own blade, his brother Uddel among them, and carries his whole dead family as a private debt. Flexible, cautious, and self-sacrificing, he watches the city''s promising young Beyonders closely — weighing which of them might carry the City of Silver''s hope of one day finding a way out of the Forsaken Land further than he can.', null, 5, 'silver', ARRAY['Colin Iliad', 'Derrick Berg', 'Lovia Tiffany'], ARRAY[7], ARRAY['city-of-silver', 'twilight-giant-pathway', 'six-member-council', 'demigod', 'spoiler'], 260),
  ('npc-daly-simone', 'Daly Simone — Spirit Medium', 'npc', 'Daly Simone is a Sequence 7 Spirit Medium of the Death pathway and a member of the Tingen Nighthawks, the division of the Church of the Evernight Goddess. A recognized genius — she reached Spirit Medium in only two years — she is about to advance to Sequence 6 and be transferred to the Backlund diocese on account of her high potential. Death is one of the Nighthawks'' own pathways, so Daly is a native Death-pathway operative, not a specialist borrowed from elsewhere. Dressed in a hooded black robe and a silver bracelet strung with a white crystal pendant, she wears makeup to look older than her years. Her craft is communion with the dead: she contracts an unnamed higher-dimensional messenger from the Spirit World, summoning it by incantation to carry her will across the boundary of the living and the dead. To colleagues she is ''Ma''am Daly'' — composed and professional in the field. Beneath that poise she carries an unconfessed, mutual love for Captain Dunn Smith of the Tingen team; neither ever spoke of it, he believing himself unworthy and she fearing she would frighten him away. It is a private grief she keeps behind her medium''s calm.', 'death', 5, 'tingen', ARRAY['Daly Simone', 'Dunn Smith'], ARRAY[7], ARRAY['nighthawks', 'death-pathway', 'spirit-medium', 'evernight-goddess', 'tingen'], 232),
  ('npc-danitz-dubois', 'Danitz Dubois — Boatswain of the Golden Dream', 'npc', 'Danitz Dubois is the fourth boatswain of the Golden Dream, the treasure-hunting pirate crew captained by the Pirate Admiral "Vice Admiral Iceberg," Edwina Edwards — a crew whose real business is not slaughter but the relics and ruins of the seas, plundering merchant and passenger ships only when the coffers run truly dry, and never harming the innocent. Danitz calls himself an adventurer who hunts treasure and a part-time pirate, and there is truth in both: cautious to the point of cowardice one moment, brash the next, forever cursing under his breath. He keeps a home in Bayam, on Amyris Avenue, bought with hard-won shares of plunder and salvage. In the great affairs stirring around the Rorsted Archipelago he will find a stranger role than any pirate expects — entrusted by his captain to serve as the Golden Dream''s quiet contact with the islands'' hidden Resistance. But for now he is a fire-wielding Beyonder of the Red Priest''s road — "Blazing," the wanted posters name him — and the fourth boatswain of a famous crew, at home in Bayam''s salt and rumour.', null, 5, 'bayam', ARRAY['Danitz Dubois', 'Edwina Edwards'], '{}', ARRAY['golden-dream', 'pirate', 'red-priest', 'bayam', 'sonia-sea'], 205),
  ('npc-darkwill', 'Darkwill — The Sarcastic Apothecary', 'npc', 'Lawson Darkwill is a chubby, round-faced man of about thirty with short black hair and brown eyes, who likes to criticize people and lace his conversation with sarcasm. At the window''s start he runs Lawson''s Folk Herb Store on Vlad Street in Tingen''s East Borough — outwardly a folk-remedy shop, in truth the practice of a Beyonder Apothecary of the Moon pathway and member of the Life School of Thought, disciple of Roy King. He owns a Beyonder owl of the Visionary pathway named Mr. Harry. Darkwill''s own reason for choosing the Apothecary path was to brew medicines that enhance sexual ability, and like some nobles he is obsessed with mummy powder. Wary of drawing the official Beyonders'' attention after treating one customer too many, he shuts the store, entrusts it to an agent for half the monthly profits paid into an anonymous Backlund bank account, and leaves the city. He resurfaces in Backlund — cultivating medicinal herbs in the sewers near Backlund Bridge, trading at Old Mister Eye of Wisdom''s gatherings, and advancing to Sequence 8 Beast Tamer — and later keeps a tiny herb store near the Red Theater in Bayam, fretting over the fate of his arrested teacher and the strange die Roy King left in his care.', null, 5, 'tingen', ARRAY['Darkwill', 'Roy King', 'Isengard Stanton'], ARRAY[8], ARRAY['apothecary', 'life-school-of-thought', 'herb-store', 'merchant', 'spoiler'], 280),
  ('npc-daxter-guderian', 'Daxter Guderian — The Asylum Doctor', 'npc', 'Daxter Guderian is a doctor of the Greenhill Mental Asylum in Tingen City, and behind that refined, gold-spectacled bearing a Beyonder of the Visionary pathway and a member of the secret Psychology Alchemists — a Sequence 9 Spectator. He was drawn into the order through the asylum itself: a patient, Hood Eugen, tempted him into becoming a Beyonder and joining the Alchemists. To advance, he slips down to the underground market beneath the Evil Dragon Bar to buy his potion ingredients, and he keeps the loose, scholarly outlook of an organisation that styles itself a circle of mind-scientists, holding to its theories of consciousness and the subconscious. An alert gentleman with a sharp eye for observation, he is a junior member who knows little of the powers above him. When Klein Moretti — a Nighthawk who first glimpsed him at that underground market and later tracked him down — visits the asylum and presses him for cooperation, Daxter agrees, becoming an informant: he hands over a Telepathist potion formula and tells Klein about Hood Eugen''s abnormality. To the city he is only a well-mannered alienist; to those who know the Beyonder world he is a thread leading into a far larger web.', null, 5, 'tingen', ARRAY['Daxter Guderian', 'Hood Eugen', 'Klein Moretti'], ARRAY[9], ARRAY['psychology-alchemists', 'visionary-pathway', 'tingen', 'informant', 'secret-organization'], 235),
  ('npc-derrick-berg', 'Derrick Berg — The Sun of the Tarot Club', 'npc', 'Derrick Berg is a young man — barely more than a boy — born and raised in the City of Silver, one of the surviving city-states clinging to life in the lightning-wracked dark of the Forsaken Land of the Gods, and one of the rare souls whose spirit found a way beyond it. His people once worshipped the Ancient Sun God, the Creator they still keep faith with in their abandoned land. Derrick was shaped by the City''s terrible curse: when its people die they must be slain by their own blood kin, or else rise as evil spirits, and Derrick was forced to put his own parents to death by his hand. In his grief and desperation he prayed over a crystal ball — one his father said a long-destroyed city had used to worship its deity — and was pulled up into the Gray Fog. There he becomes a member of the Tarot Club under the code name "The Sun." His sincerity and the Sun pathway''s raw strength make him a reliable ally, though his youth and honesty leave him easily taken advantage of by subtler members like The Hanged Man, and an unwitting source of comedy among them. His defining ties are to his lost home and its faith and — through the Tarot Club — a growing bond with The Fool (Klein Moretti) and the others gathered above the gray fog. Derrick''s arc is that of a sheltered believer discovering how vast and dangerous the real world is, without ever losing the openhearted decency the City raised in him.', null, 5, 'silver', ARRAY['Derrick Berg', 'Klein Moretti', 'Alger Wilson'], '{}', ARRAY['forsaken-land', 'city-of-silver', 'tarot-club', 'the-sun', 'sun-pathway', 'ancient-sun-god'], 245),
  ('npc-edwina-edwards', 'Edwina Edwards — Archbishop and Pirate Admiral ''Iceberg''', 'npc', 'Edwina Edwards is an Archbishop of the Church of the God of Knowledge and Wisdom — and, to the navies of the world, the Pirate Admiral "Vice Admiral Iceberg," captain of the Golden Dream with a great bounty on her head. Born in Lenburg, descended from a follower of Roselle Gustav whose family fled and converted to the wisdom-faith, she is a Mysticism Magister, a Sequence 5 of the White Tower Pathway. She commands a crew of subordinates across the seas and keeps an old friendship with Anderson Hood, the Fog Sea''s strongest hunter, from their schooldays at the Church''s college. In the great events of the age she becomes an ally of the adventurer Gehrman Sparrow, lending the White Tower''s learning to causes that reach far beyond Lenburg''s borders. Few embody the Church''s prizing of talent over birth so plainly as a scholar-magister who is also a pirate.', null, 5, null, ARRAY['Edwina Edwards', 'Anderson Hood'], ARRAY[4], ARRAY['god-of-knowledge', 'archbishop', 'white-tower-pathway', 'pirate', 'lenburg'], 200),
  ('npc-gaard-ii', 'Gaard II — Pontiff of the Lord of Storms', 'npc', 'Gaard II is the Pontiff of the Church of the Lord of Storms and the spokesman of the storm-god himself, seated at the Chasm of Storms Cathedral on Pasu Island. Though he wears the face of a man in his forties, he has led the Council of Cardinals for nearly a century; crowned with a triple diadem of sapphire and emerald and robed in storm-dark blue shot with gold and silver, he carries himself like a gathering tempest. As Head of the Council of Cardinals he commands both the Church''s clergy and its Beyonder arm, the Mandated Punishers, who take their orders directly from the Council. He is a Calamity, a Sequence 2 Angel of the Tyrant Pathway and a Mythical Creature beneath the man''s shape. To the faithful of the seas he is the nearest thing to the Lord of Storms made flesh — the voice through which the King of the Skies and Emperor of the Seas speaks to his Church.', null, 5, null, ARRAY['Gaard II'], ARRAY[2], ARRAY['lord-of-storms', 'pontiff', 'tyrant-pathway', 'mandated-punishers'], 210),
  ('npc-haiter', 'Haiter — Tomb-Bound High Priest of Death', 'npc', 'Haiter leads the Artificial Death Faction of the Numinous Episcopate out of West Balam, on the Southern Continent — and he is old beyond ordinary reckoning, for he was once the High Priest of the Church of Death in the days of the Balam Empire itself, and later received the dead god''s grace to rise as an angel of the faith: a Death Consul who has carried that devotion down the long centuries since the empire fell. But a ritual went wrong. Haiter was severely eroded in the ceremony and has not left his tomb since, working through subordinates to gather what his cause requires. Where the strongest Royal Family Faction gathers about the thinning Eggers bloodline under the Pale-White Empress, Haiter''s faction pursues the older, colder road — the Artificial Death working, an attempt to fashion a vessel for the god by craft and ritual rather than by blood. He keeps three saints and an angel about him in the colony, treats the orthodox churches'' centuries of persecution as a delay rather than a defeat, and reckons time in epochs. Confined, eroded, and utterly committed, he intends still to see Death walk the world again.', null, 5, 'balam', ARRAY['Haiter', 'Sia Palenque Eggers'], ARRAY[4], ARRAY['numinous-episcopate', 'church-of-death', 'death-pathway', 'balam', 'southern-continent', 'spoiler'], 238),
  ('npc-hawick', 'Hawick — The Former Chief of the City of Silver', 'npc', 'Hawick was the Chief of the City of Silver before Colin Iliad and an Elder of its six-member council — a demigod who rose to Sequence 4 Demon Hunter of the Twilight Giant pathway, and an old, close colleague of Colin''s. His story is the city''s great cautionary tale of pathway switching. Lacking the Sequence 3 Silver Knight formula, the City of Silver''s Beyonders were capped at demigod for generations — until an expedition recovered the Sequence 3 formula of the adjacent Death pathway: Ferryman. Hawick attempted the switch. He built an inverted mausoleum reaching deep underground and moved into it, intending to cultivate it into his own Underworld for the altered advancement ritual. Afterward he appeared less and less, until the mausoleum''s main door could no longer be opened. The ritual failed — corrupted by the influence of Artificial Death — and Hawick mutated into a rampaging, incomplete mythical creature: nearly four meters tall, long-limbed, covered in white feathers stained with faint yellow oil, thin illusory black tubes trailing from his back into infinity. In the summer of 1350 Colin Iliad, Waite Chirmont, and Lovia put him down in his own mausoleum, Colin painfully delivering the final blow. His Beyonder characteristic fused with his skull into the Sealed Artifact Twilight Mask, which later served as an anchor in Colin''s own Silver Knight advancement ritual.', null, 5, 'silver', ARRAY['Hawick', 'Colin Iliad', 'Waite Chirmont', 'Lovia Tiffany'], ARRAY[6], ARRAY['city-of-silver', 'pathway-switching', 'death-pathway', 'twilight-giant-pathway', 'loss-of-control', 'spoiler'], 300),
  ('npc-hidden-sage', 'The Hidden Sage — The Knowledge That Came Alive', 'npc', 'The Hidden Sage is not a man. It is the Hermit pathway''s Uniqueness come to life — a quasi-Sequence 0 existence of pure, sentient knowledge that manifests as an illusory light of massive, tangled information, or as a pair of ruthless, lashless, almost transparent eyes glimpsed behind a victim''s shoulder. He routinely watches and tests every Beyonder of the Hermit pathway, especially at the moment of Sequence advancement, whispering knowledge into their ears — knowledge that is orthodox and correct, but delivered so relentlessly that a listener who cannot digest it becomes a raving lunatic or an outright monster. The Moses Ascetic Order venerates him as its god and has mastered comparatively safe methods of listening; for everyone else on the pathway the whispers are a death sentence deferred. In Tingen he stood behind Old Neil of the Nighthawks before the old man''s madness forced his colleagues to kill him. Because the Hidden Sage exists, no true Sequence 0 of the Hermit pathway can — Roselle Gustav could only rise to Sequence 1 Knowledge Emperor with the Sage abroad. He is knowledge without dignity, humanity, or malice as humans know it: only the instinct to continue, and the endless need to be heard.', null, 5, null, ARRAY['Hidden Sage', 'Old Neil', 'Roselle Gustav'], ARRAY[4], ARRAY['hidden-sage', 'hermit-pathway', 'moses-ascetic-order', 'uniqueness', 'spoiler'], 270),
  ('npc-horamick-haydn', 'Horamick Haydn — Archbishop of Steam and Machinery', 'npc', 'Horamick Haydn is an Archbishop of the Church of the God of Steam and Machinery and a member of its Divine Council, presiding over the Backlund diocese. He leads a double life that the machine-faith finds no contradiction in: an emeritus professor of physics at Backlund University and a celebrated scientist, he is also a leader within the Machinery Hivemind and an Alchemist — a Sequence 4 demigod of the Paragon Pathway. In him the Church''s love of invention and its Beyonder power meet in one man, equally at home before a lecture hall and at the head of a Hivemind team addressing supernatural incidents and hunting down wild Beyonders. Patient and exacting, he embodies the Church''s creed that God lets those who wish to be strong be made strong — and that knowledge and machinery, rightly mastered, are themselves a kind of worship.', null, 5, 'backlund', ARRAY['Horamick Haydn'], ARRAY[4], ARRAY['god-of-steam', 'archbishop', 'machinery-hivemind', 'paragon-pathway', 'backlund'], 195),
  ('npc-hvin-rambis', 'Hvin Rambis — Mr. Pride', 'npc', 'Hvin Rambis is the Loen royal family''s consultant of more than a decade and a publicly recognized scholar — an elder with lush, completely white hair, blue eyes that seem to hide wisdom, a warm and elegant bearing, and a reputation as an amiable, humorous, true gentleman of excellent character. A Berth University graduate of aristocratic background, he is famed for profound knowledge and outstanding insight, rational and objective in all matters. The public face conceals Mr. Pride: one of the councilors of the Psychology Alchemists, in charge of the Backlund area, and a demigod of the Visionary pathway — a Sequence 4 Manipulator whose Pride mask feeds an arrogance that makes him look down on weaker Beyonders. He carries the Rotting Meteor. During the window he works to incite revolution in Loen by deepening the cracks between the New Party and the Conservative Party: he engineers the suicide of the businessman Cuarón, using Cuarón''s shares as bait in a meticulous trap for Syndras, and hypnotizes the young noblewoman Audrey Hall — who came to him for the Sequence 5 Dreamwalker potion formula — turning her into an unwitting informant on her father Earl Hall''s political movements. As a late development his cult ties surface — identified as a cultist and wanted by all three Churches, he disappears before the warrant can even be issued, and Backlund society puzzles over the vanished gentleman-scholar.', null, 5, 'backlund', ARRAY['Hvin Rambis', 'Audrey Hall', 'Syndras', 'Earl Hall', 'Cuarón', 'Pauli Derlau'], ARRAY[4], ARRAY['psychology-alchemists', 'royal-consultant', 'visionary-pathway', 'demigod', 'conspiracy', 'spoiler'], 285),
  ('npc-ian-wright', 'Ian Wright — The Old Geezer of Bravehearts Bar', 'npc', 'Ian Wright — "Old Geezer" to those who know him — is a boy of fifteen or sixteen working as a black-market arms dealer and intelligence peddler out of the Bravehearts Bar on Backlund Bridge. He looks adolescent, with refined features and the bright red eyes of his dead father; the Sanguine Emlyn White reckons him a likely descendant of that blood, though Ian himself is no Beyonder. For trade he wears an old overcoat and brown bowler and glues two whiskers above his lip to look older. He is unnervingly mature, observant, and meticulous to the point of compulsion. Ian was one of several vagrant children adopted and trained in intelligence work by Detective Zreal Viktor Lee, secretly a spy for the Feysac Empire. In 1349 he stumbled onto clues to a manuscript of Turani von Helmosuin, father of the second-generation difference machine, and was swept into the spy war between Intis intelligence and MI9: Zreal vanished (dead on Iron Carbon Street), the Zmanger gang hunted Ian, and he hired the detective Sherlock Moriarty — Klein Moretti''s cover identity — to investigate. Captured and released by MI9, he laid low in Pritz Harbor before returning to Backlund, replacing the dead Kaspars Kalinin at the Bravehearts Bar with the quiet backing of Sharron and Maric. Emlyn White has since hired him to dig up word of Primordial Moon believers.', null, 5, 'backlund', ARRAY['Ian Wright', 'Klein Moretti', 'Emlyn White', 'Sharron', 'Maric', 'Kaspars Kalinin'], ARRAY[8], ARRAY['black-market', 'intelligence-peddler', 'bravehearts-bar', 'backlund-bridge', 'civilian', 'spoiler'], 285),
  ('npc-ilya', 'Ilya — The Goddess''s Eye', 'npc', 'Ilya is one of the thirteen archbishops of the Church of the Evernight Goddess, known in the Beyonder world as "The Goddess''s Eye," and is chiefly responsible for the Church''s affairs on the Southern Continent. She is a Sequence 3 Horror Bishop of the Darkness pathway — a living Saint. She has beautiful raven-black hair and an exquisite face whose age no one can tell; her eyes seem to contain countless stars. In the story''s present she directs the Church''s response to the Numinous Episcopate stirring in the colonies: when Soest''s Red Gloves team — Leonard Mitchell and Daly Simone among them — is sent south to investigate, Ilya supplies Sealed Artifacts and groundwork. The investigation uncovers the disgraced former bishop Ince Zangwill operating there, possibly ridden by an evil spirit of the Red Priest pathway. Bound to secrecy by the trait of the Sealed Artifact 0-08 he carries, Ilya sets a trap with a Grade 1 Red Priest artifact as bait — not knowing Zangwill''s true aim is to hunt HER, to claim her Beyonder characteristic for his own advancement. She arrives too late for the kill that ends him, but pries crucial intelligence from his remnant spirit, including his dealings with the royal family and the Demoness Sect — and the fact that the "dead" Nighthawk Klein Moretti lives, which the Holy See orders kept strictly confidential.', null, 5, 'balam', ARRAY['Ilya', 'Ince Zangwill', 'Leonard Mitchell', 'Daly Simone', 'Soest', 'Klein Moretti'], ARRAY[4], ARRAY['evernight-church', 'archbishop', 'saint', 'southern-continent', 'numinous-episcopate', 'spoiler'], 285),
  ('npc-ince-zangwill', 'Ince Zangwill — The Fugitive Archbishop', 'npc', 'Ince Zangwill is a former Archbishop of the Church of the Evernight Goddess and the primary antagonist of the Tingen arc. A Beyonder of the Death Pathway who reached Sequence 5, Gatekeeper — but failed his promotion — he defected from the Church, stealing 0-08: the Quill of Alzuhod, a Grade 0 sealed artifact and one of the most dangerous the Church holds. This living quill makes what it writes come true whenever the outcome is possible, its power mirroring the Visionary Pathway''s Author — but it perpetually tries to kill its own wielder, a murderous price that dogs Zangwill for the rest of his life. Hunted by the Nighthawks, he uses 0-08 to orchestrate a chain of coincidences in Tingen City, engineering the theft of Saint Selena''s Ashes so he can switch pathways and advance to Sequence 4, Nightwatcher of the Darkness Pathway. That scheme kills numerous civilians and Nighthawks — among them Megose, Captain Dunn Smith, and Klein Moretti, though Klein later resurrects. Zangwill''s true drives are ambition and vengeance: bitter at the Church for casting him aside, he means to make it pay. His downfall comes much later when Klein, aided by Leonard Mitchell, Daly Simone, and the Author Adam working from the shadows, finally hunts him down and kills him.', 'darkness', 5, 'tingen', ARRAY['Ince Zangwill', 'Klein Moretti', 'Dunn Smith', 'Megose'], ARRAY[5], ARRAY['antagonist', 'nighthawks', '0-08-card', 'darkness-pathway', 'betrayal', 'death-pathway', 'church-of-the-evernight-goddess'], 240),
  ('npc-jahn-kottman', 'Jahn Kottman — The Sea King of Bayam', 'npc', 'Jahn Kottman is a Cardinal of the Church of the Lord of Storms and a high-ranking deacon of the Mandated Punishers — and, until the war''s end, was the true ruler of the Beyonder world in the Rorsted Archipelago, holding it from the Cathedral of Waves in Bayam as its Archbishop. Brawny and deep-lined, his deep-blue hair thick as a knot of tentacles, he is aggressive and impulsive in the way of his pathway — a Sea King, a Sequence 3 of the Tyrant Pathway who boasts that in his waters even a War Bishop must bow his head. He once contained the rampage of the dying Sea God Kalvetua and moved to claim his Beyonder Characteristics, only to be beaten to the corpse by the Fool. When the bounty hunter Gehrman Sparrow drew his eye at Bayam, Kottman recognized and reported him, seeing a bounty placed on his head; later he crushed a War-Bishop-led naval invasion of the port during the World War. His rivalries run from the Rose School of Thought to the man behind Gehrman Sparrow''s many masks. After the war his archipelago seat passed to Alger Wilson.', null, 5, 'bayam', ARRAY['Jahn Kottman', 'Klein Moretti', 'Gehrman Sparrow', 'Kalvetua'], ARRAY[3], ARRAY['lord-of-storms', 'cardinal', 'sea-king', 'tyrant-pathway', 'bayam', 'mandated-punishers'], 240),
  ('npc-jason-rose-school', 'Jason — Rose School Enforcer', 'npc', 'Jason is an enforcer of the Rose School of Thought''s Indulgence Faction and a Sequence 6 Zombie of the Chained pathway. His complexion is pale, his face marked with indistinct dark patches like half-healed rot, and the malice in his eyes is completely undisguised — he looks less like a man than a zombie craving fresh flesh. In the autumn of 1349 he came to Backlund with his fellow Beyonders Steve and Tyre, under Lord Steve''s lead, to hunt the Temperance Faction exiles Sharron and Maric. The hunters kept watch on the Bravehearts Bar and deliberately set a gang on the bar''s dealer Kaspars to squeeze the exiles into a trap. Sharron and Maric, needing an edge, hired the detective Sherlock Moriarty — Klein Moretti''s cover identity — to help eliminate the three pursuers. In the battle that followed, Jason lectured the weaker Maric on failing to grasp "the power of desire" moments before being killed by Sharron and Sherlock Moriarty, dragged into another realm by Sharron''s power. He is an early-window presence: afterward he matters as a corpse — proof of how far the Indulgence Faction will reach into the capital to punish its apostates, and of what the exiles at the Bravehearts Bar are still running from. He is no relation to Jason Beria, the Desire Apostle of the Beria family.', null, 5, null, ARRAY['Jason', 'Steve', 'Tyre', 'Sharron', 'Maric', 'Klein Moretti', 'Jason Beria'], ARRAY[6], ARRAY['rose-school', 'indulgence-faction', 'enforcer', 'chained-pathway-figure', 'bravehearts-bar', 'spoiler'], 270),
  ('npc-kaspars-kalinin', 'Kaspars Kalinin — Bravehearts Bar Fixer', 'npc', 'Kaspars Kalinin is a black-market arms dealer and intelligence peddler who holds court at the Bravehearts Bar by Backlund Bridge. A fifty-year-old with a deep voice, a huge twisted scar running from the corner of his right eye to the side of his mouth, a nose reddened into a "brandy nose" by drink, and a bad leg that keeps him on a crutch, he is an alcoholic with a slight fear of Beyonders — yet he is precisely the door through which ordinary people first reach them. Unlike "Old Geezer" Ian Wright, he keeps a deeper relationship with wild mid-Sequence and lower Beyonders, and he is mainly tied to the Eye of Wisdom''s Beyonder Gatherings. A believer of the Lord of Storms, he sells firearms, replacement non-Beyonder ammunition, and explosives. In September 1349 he supplies the private detective Sherlock Moriarty (Klein Moretti) with a source for private firearms and introduces him to the Beyonder bodyguard Maric. His indirect association with the Rose School of Thought''s Temperance faction makes him collateral in that sect''s internal war: a gang induced by the Indulgence faction briefly drives him from the bar in early October, though he returns by October 20. By early December 1349 he is confirmed long dead in his bed of an unknown mystical suffocation — collateral of the Indulgence faction''s revenge on Maric and Sharron for hunting their members. His trade passes to "Old Geezer" Ian Wright.', null, 5, 'backlund', ARRAY['Kaspars Kalinin', 'Klein Moretti', 'Maric', 'Isengard Stanton', 'Ian Wright'], ARRAY[8], ARRAY['backlund', 'black-market', 'informant', 'bravehearts-bar', 'rose-school-of-thought', 'spoiler'], 265),
  ('npc-lanevus', 'Lanevus — The Wanted Swindler', 'npc', 'Lanevus is a swindler with a plump forehead, black hair, brown eyes, and near-round spectacles, wearing a faint smirk as though mocking everyone — otherwise so ordinary he vanishes in a crowd. He is a Sequence 8 Swindler of the Error pathway, affiliated with the Aurora Order and carrying a Hermits of Fate''s Badge. Early in the window he works Tingen''s investing circles: claiming to have found a rich, high-quality iron deposit in the Hornacis Mountain Range, he founds a steelworks company that exists only on paper, issues shares, promises substantial returns, and vanishes with over ten thousand pounds from more than a hundred victims — earning a hundred-pound bounty from the Loen Kingdom. Behind the fraud lies something darker. Recognized for his cunning by the cultist Sirius Arapis (a Secrets Suppliant of the Aurora Order), Lanevus learned of a ritual to summon a spawn of the True Creator; he courted and became engaged to Megose, manipulating her into serving as its vessel, and deceived Hood Eugen into assisting. He then flees under aliases such as El and Kevin, leaving taunting clues — a "bomb" left growing in Tingen — and hides around Backlund''s East Balam Docks. As a late development, the True Creator''s hidden "sapling" turns his body into a vessel; the Aurora Order seizes and guards him, and after the aborted descent he is slain in Backlund''s sewers by Mr. Fool''s hand.', null, 5, null, ARRAY['Lanevus', 'Sirius Arapis', 'Megose', 'Hood Eugen'], ARRAY[8], ARRAY['swindler', 'aurora-order', 'fugitive', 'true-creator', 'spoiler'], 270),
  ('npc-larrion', 'Larrion — Chief Shepherd of the God of Combat', 'npc', 'Larrion is the Chief Shepherd of the Church of the God of Combat, the highest operational hand of the war-faith in the Feysac Empire. Over 2.6 metres tall, light-blue-eyed, speaking in a rough country dialect, he is a Glory — a Sequence 2 Angel of the Twilight Giant Pathway — and fanatically loyal, willing to make of his own body a vessel for his god''s return. When the God of Combat was slain at Backlund near the close of the World War, Larrion destroyed the Church''s records of its Grade 0 Sealed Artifacts and fled with the Trunsoest Brass Book (0-02), trapping his pursuers in Belltaine City; confronted there by the Evernight Goddess''s Arianna and by Klein Moretti, he lost some of his Beyonder characteristics but escaped through the Spirit World, his fate unknown to them. He believes, against all evidence, that his god will rise again in his own body — and waits.', null, 5, 'feysac', ARRAY['Larrion', 'Arianna', 'Klein Moretti'], ARRAY[2], ARRAY['god-of-combat', 'chief-shepherd', 'twilight-giant-pathway', 'feysac'], 205),
  ('npc-lawrence-nord', 'Lawrence Nord — The Abraham Elder', 'npc', 'Lawrence Nord is an old man of about eighty with wrinkled blue eyes, a heavy woolen coat, and a black half top hat — and a member of the Abraham Family''s Elder Council, a Sequence 7 Astrologer of the Door pathway. He once worked as a public school teacher in Constant City, Midseashire. When the family disciple Botis joined the Aurora Order and betrayed the Abrahams, the massacre all but wiped out their upper echelons; all of Lawrence''s children and his brother Richard died, and Lawrence survived grievously injured. Unwilling to live amid the survivors'' sighing despair, he found a reason to leave the Elder Council and came to Backlund in late 1349 to seek his other brothers, Laubero and Sam. At their Cherwood Borough residence he instead met the young Beyonder Fors Wall, who told him Laubero and his wife Aulisa were already dead. His health failing, Lawrence met Fors again while visiting the graves at Grimm Cemetery; a severe coughing fit felled him, and he died of cardiac arrest. Trusting Fors for her kindness to Aulisa, his dying wish was that she deliver his belongings — including the mystical book Leymano''s Travels and the Beyonder characteristic soon to precipitate from his corpse — to Dorian Gray Abraham in Pritz Harbor. His epitaph reads simply: "He''s a good teacher."', null, 5, 'backlund', ARRAY['Lawrence Nord', 'Fors Wall', 'Botis', 'Aulisa', 'Dorian Gray Abraham'], ARRAY[6], ARRAY['abraham-family', 'elder-council', 'door-pathway-figure', 'grimm-cemetery', 'dying-wish', 'spoiler'], 275),
  ('npc-lovia-tiffany', 'Lovia Tiffany — Elder of the Six-Member Council', 'npc', 'Elder Lovia Tiffany sits on the City of Silver''s six-member Council — a striking woman of nearly one point nine metres, silver-gray hair curling loose, light gray eyes that seem to pierce the soul, robed in black worked with strange purple patterns. She is a Beyonder of the Hanged Man pathway at Sequence 5, a Shepherd, grazing the souls of fallen Beyonders to wield fragments of their power; the city''s formulas for her pathway run only to Sequence 5, yet she once defeated a high-Sequence evil spirit unwounded, and the Council seated her by special exception. Her moods turn without warning — weeping, sneering, indifferent by turns, the mark of her unstable pathway. She lost her husband on a temple expedition from which every other member came back mad or dead, and the city''s crueler whispers say she ate him. The truth is darker: on that expedition Lovia was touched by the sealed evil god her pathway serves, and she believes in secret that the True Creator''s help is the city''s one way out of the Forsaken Land. Strangely, since that contact her temperament has grown calmer. She remains genuinely, fiercely loyal to the City of Silver — which is exactly what makes her faith so dangerous.', null, 5, 'silver', ARRAY['Lovia Tiffany', 'Colin Iliad'], ARRAY[4], ARRAY['city-of-silver', 'hanged-man-pathway', 'six-member-council', 'true-creator', 'spoiler'], 275),
  ('npc-madam-sharon', 'Madam Sharon — The Socialite of Tingen', 'npc', 'Madam Sharon is a famous socialite of Tingen City — the second wife, now widow, of old Baron Khoy. She favors long black dresses that set off fair, smooth skin, waterfall-like brown hair, and crystal-clear brown eyes; she carries the mature vibe of a woman in her thirties with a remnant of innocence. From her residence on Osna Street she keeps "friendly" terms with many nobles and senior civil servants as far away as Backlund, and is welcomed among the nouveau riche — a guest whom both the Conservative Party and the New Party will happily seat at their banquets. The charm hides a Sequence 6 "Pleasure" of the Demoness pathway and a member of the Demoness Sect: she keeps a White Primordial Demoness Figurine hidden in a safe, and it was she who passed the Witch potion formula to Tris. Early in the window, the madness accumulated since her advancement — nudged by the arrangements of Sealed Artifact 0-08 (the Quill of Alzuhod) — drives her to risk murdering Member of Parliament John Maynard, drawing police pressure and a Nighthawks mediumship investigation onto Tingen. As a late development the Nighthawks corner her in September 1349; forced into a dream, she is slain, and the Tingen City Honest Paper prints a tidy story about a pagan ceremony and a heroic dead police officer.', null, 5, 'tingen', ARRAY['Sharon', 'Tris', 'John Maynard'], ARRAY[7], ARRAY['demoness-sect', 'socialite', 'tingen-society', 'widow', 'spoiler'], 270),
  ('npc-matriarch-roland', 'Matriarch Roland — Leader of the Church of the Earth Mother', 'npc', 'Roland is the Matriarch of the Church of the Earth Mother — the leader of the whole life-faith — ruling from its seat in the Feynapotter Kingdom. She is a Desolate Matriarch, a Sequence 2 Angel of the Mother Pathway, the living head of a Church that prizes fertility and the return of every soul to the Mother''s embrace. The Church''s gravest fear runs close to her throne: the false revelations of the Mother Goddess of Depravity — the very deceit the Church''s split into Favored and Blessed was meant to guard against — press nowhere harder than upon the Matriarch''s seat. It is precisely because a Matriarch could fall this way that no order of the Church may issue without the countersignature of both its halves. That the danger shadows even her is among the signs that the Earth Mother''s house, for all its talk of life, stands nearer the abyss than any of the orthodox faiths.', null, 5, null, ARRAY['Roland'], ARRAY[2], ARRAY['earth-mother', 'matriarch', 'mother-pathway', 'feynapotter'], 210),
  ('npc-melissa-moretti', 'Melissa Moretti — Klein''s Sister', 'npc', 'Melissa Moretti is the youngest Moretti sibling and Klein''s younger sister in his adopted identity. She is a frugal, diligent sixteen-year-old student in the Steam and Machinery department of Tingen Technical School, whose tuition the household scrimps to afford. Melissa is practical, highly rational, and slightly stern — she manages the household budget, does the family cooking, skips small comforts to save pocket change, and worries about Klein''s erratic behavior after his "illness" (the transmigration). She represents Klein''s primary emotional anchor to his new life and identity: protecting Melissa and ensuring her wellbeing becomes one of his core motivations. In this early Tingen period she claims not to believe in the supernatural and is unaware of the Beyonder world and Klein''s Nighthawk activities. Their modest rented apartment on Iron Cross Street, in the West Borough of Tingen City, is the domestic center of Klein''s early life there. Melissa embodies the ordinary people whom the Beyonder organizations strive to protect — living in a world where supernatural horrors lurk just beyond perception, shielded only by the efforts of people like her brother. Klein''s determination to keep her safe and ignorant of the dangers he faces drives many of his decisions. Benson Moretti, their eldest brother, lives with them and carries the household as its main breadwinner, working as a clerk at an import-export firm.', null, 5, 'tingen', ARRAY['Melissa Moretti', 'Benson Moretti'], '{}', ARRAY['family', 'civilian', 'anchor', 'iron-cross-street'], 240),
  ('npc-mr-a', 'Mr. A — Oracle of the Aurora Order', 'npc', 'Mr. A is one of the twenty-two Oracles of the Aurora Order, a worshipper of the True Creator who organizes secret Beyonder gatherings in Backlund where all manner of trades are made and brokered. He appears always in a hooded robe, his looks hidden in shadow; beneath the hood is a beautiful, devilishly feminine face and eyes that hold extreme madness and confidence. He is a Sequence 5 Shepherd of the Hanged Man pathway, able to graze up to seven Beyonders'' souls and borrow their abilities — his stolen flock spans a Desire Apostle of the Abyss, an Affliction of the Demoness pathway, a Baron of Corruption, a Scribe of the Door pathway, a Wind-blessed, a Soul Assurer, and a Doctor of the Mother pathway. His great goal is to let the True Creator descend onto the land; each failure earns punishment from his god, and regulars at his gatherings notice the change — once carefree and supercilious as a mountain, he grows repressed and far more dangerous, like a reared-up snake sticking out its tongue. Acting on a "divine epiphany," he begins hunting certain blessed individuals through his own gatherings, and partners with Lady Despair, Panatiya of the Demoness Sect, toward a large-scale sacrificial ritual in Backlund. As a late development he is erased to a fog-shrouded exile by a Grade 0 Sealed Artifact and perishes there in June 1350.', null, 5, null, ARRAY['Mr. A', 'Panatiya'], ARRAY[6], ARRAY['aurora-order', 'oracle', 'hanged-man', 'secret-gatherings', 'spoiler'], 290),
  ('npc-old-neil', 'Old Neil — Nighthawk Clerk & Mysticism Tutor', 'npc', 'Old Neil (Neil Townsend) is a clerk at the Blackthorn Security Company in Tingen City and a former Nighthawk, retired from field duty because his advanced age and failing health made cases unsuitable for him. Rather than resting at home, he prefers the company of documents and records. He follows the Hermit Pathway at a low rank — a Sequence 9 Mystery Pryer — and holds to the maxim ''Do as you wish but do no harm.'' Warm, humorous, if famously stingy, he serves as Klein Moretti''s instructor in early Mysticism, teaching Cogitation, Spirit Vision, Divination, Ritualistic Magic, Honorific Names, mystical items and ingredients, and the practical lore formal training omits; he also introduces Klein to Tingen''s underground market and his old friend Swain. Old Neil''s fate is one of the Tingen arc''s most poignant tragedies: haunted by his inability to save his terminally ill fiancée Celeste and inspired by the ravings of the Hidden Sage, he secretly pursues a forbidden working — crafting an ''Alchemical Life'' to resurrect her — and loses control, transforming into a monster. Klein Moretti, Dunn Smith, and Royale Reideen confront him at his residence; Dunn subdues him with the Peaceful Hair Strands, and Old Neil, pleading for mercy, dies. His epitaph reads: ''If I cannot save her, then I shall accompany her.''', null, 5, 'tingen', ARRAY['Old Neil', 'Neil Townsend'], ARRAY[9, 8], ARRAY['nighthawks', 'clerk', 'mysticism-tutor', 'mentor', 'tragedy', 'loss-of-control'], 250),
  ('npc-pallas-negan', 'Pallas Negan — Duke Negan', 'npc', 'Pallas Negan, Duke Negan, is one of the richest and most powerful aristocrats in the Loen Kingdom — holder of the largest lands outside the royal family, elder brother of Prime Minister Aguesid Negan, and the main pillar of the Conservative Party in the House of Lords. A decorated former soldier who wears military uniform on formal occasions, he is also, secretly, a Sequence 6 Judge of the Justiciar pathway and a staunch believer of the Lord of Storms — a key channel of that Church''s influence on Loen politics. In September 1349 the pirate admiral Qilangos infiltrated one of his balls to assassinate him on the Twilight Hermit Order''s commission, and was foiled when Audrey Hall saw through the disguise. Negan turned deeply cautious afterward: an unpredictable schedule, mistresses moved near the Holy Wind Cathedral, a Wind-Blessed guard, and a dark blue conch that summons Archbishop Ace Snake when blown. It was not enough. On December 16th, 1349 he was assassinated by the Desire Apostle Jason Beria — another Twilight Hermit Order commission, paid with the Abyss Card of Blasphemy — with his own secretary Lockhart Siakam, a Sequence 5 Black Emperor Beyonder of MI9, conspiring in the betrayal. His death split the House of Lords and stalled a raft of bills, from worker salaries to the Poor Law. Frame him as an early-window presence whose fall keeps rippling through Backlund politics.', null, 5, 'backlund', ARRAY['Pallas Negan', 'Aguesid Negan', 'Qilangos', 'Audrey Hall', 'Jason Beria', 'Lockhart Siakam', 'Ace Snake'], ARRAY[6], ARRAY['duke', 'house-of-lords', 'conservative-party', 'storms-church', 'assassination', 'spoiler'], 290),
  ('npc-patrick-bryan', 'Patrick Bryan — The Hidden Undying', 'npc', 'On the surface, Patrick Bryan is a Backlund businessman of about thirty who owns two garment factories and worships the Evernight Goddess. He has black hair, brown eyes, and cut facial features — a classic Loenese man — wears a silk top hat, and carries a cold demeanor that discomfits no one, resembling instead the night view of a suburban cemetery. The faith is a mask: Bryan is secretly a demigod of the Death pathway, a Sequence 4 Undying, and a member of the Numinous Episcopate''s Artificial Death faction, with twelve of the sect''s Beyonders under him in Backlund. Years ago he did business in East Balam and nearly died of disease; members of the Numinous Episcopate saved him, gave him potions, and inducted him into the faith of Death. In truth he was likely an experimental subject — something unexpected in the attempt left him alive and connected to Artificial Death, and the faction came to view him as the key to that project''s success, advancing him to demigod in a mere ten years, though his knowledge of Artificial Death differs greatly from reality. His distant master is Haiter, the sealed former High Priest who leads the Artificial Death faction, and he calls a contracted messenger to run his errands. During this window he waits on revelations from the god he serves and on directives from the Southern Continent — while his masters begin to question whether his loyalty still holds.', null, 5, 'backlund', ARRAY['Patrick Bryan', 'Haiter'], ARRAY[4], ARRAY['numinous-episcopate', 'artificial-death', 'businessman', 'demigod', 'spoiler'], 278),
  ('npc-plessy-descartes', 'Cardinal Plessy Descartes — Head of the Trier Diocese', 'npc', 'Cardinal Plessy Descartes oversees the Trier diocese of the Church of the Eternal Blazing Sun from Saint Viève Cathedral in the Island District. An elderly man with high cheekbones and grizzled blond hair, his demeanor lacks sternness, yet a radiant glow clings to him that makes direct eye contact impossible and leaves the room eerily devoid of shadows — the mark of a Saint-tier Beyonder, though which road carried him so high is not spoken of. He is the Church''s senior authority in the capital: he commands its clergy, blesses its rites, and directs its sterner work, summoning Purifiers of the Inquisition to Saint Viève Cathedral and raising the deserving among them to the rank of deacon. Patient, watchful, and devoted to the radiant order of the sun-faith, the Cardinal is the human face of the Church''s power in Trier — the man through whom its will reaches both the pulpit and the shadows the Inquisition is set to burn.', null, 5, 'trier', ARRAY['Plessy Descartes'], ARRAY[4], ARRAY['trier', 'eternal-blazing-sun', 'cardinal', 'inquisition', 'saint', 'unknown-pathway'], 210),
  ('npc-portland-moment', 'Portland Moment — Chancellor and Appraiser', 'npc', 'Portland Moment is the chancellor of the Backlund University of Technology, a former full-time professor of engineering at Backlund University, and a former fellow of the Loen Kingdom Imperial Science Institute. A big-built man in his sixties with a ruddy complexion and thick white hair, his classic Loenese features are unremarkable; his reputation is anything but. Discoverer of several metal alloys used across ship and steam-engine construction, winner of the Light of Machinery award, he stands second only to figures like Turani von Helmosuin in the academic world, and the licensing patents alone have made him a tycoon worth hundreds of thousands of pounds. He is a believer of the God of Steam and Machinery — his wife worships the Evernight Goddess — so they live at Unit 100 Böklund Street near Saint Samuel Cathedral, where visiting bishops are a common sight. Secretly, he is a Sequence 7 Appraiser of the Paragon pathway. In the story''s present he is the neighbor of the tycoon Dwayne Dantès (one of Klein Moretti''s cover identities), courts the Loen Charity Bursary Foundation — where Dantès and Audrey Hall preside — for donations toward a new mechanical laboratory, and mentors Melissa Moretti, a gifted assistant in his workshop whose diligence has won his particular favor and patronage.', null, 5, 'backlund', ARRAY['Portland Moment', 'Klein Moretti', 'Audrey Hall', 'Melissa Moretti'], ARRAY[8], ARRAY['backlund-university', 'chancellor', 'appraiser', 'steam-church', 'academia', 'spoiler'], 258),
  ('npc-qilangos', 'Qilangos — Vice Admiral Hurricane', 'npc', 'Qilangos, "Vice Admiral Hurricane," was one of the seven Pirate Admirals, carrying a 30,000-pound bounty. Though only a Sequence 6 Wind-Blessed of the Tyrant pathway, he held admiral''s rank on the strength of his Sealed Artifact, Creeping Hunger: a thin human-skinned glove given to him by the Twilight Hermit Order, which stores souls and lends their Beyonder abilities — and demands a soul and flesh each day, making him a practiced serial killer who kills at least one person daily to feed it. He was a cold-blooded lone wolf who trusted no one, yet cautious enough to always arrange an escape route. He came from the same village as Alger Wilson; both had been servants in the same chapel under a brutal priest before Qilangos secretly fled to piracy on the Sonia Sea, coercing Alger for years after. Together they once found the primitive island whose cathedral catacombs hid the Tyrant Card of Blasphemy he was too low-sequence to claim. In September 1349, on the Order''s commission, he infiltrated a ball hosted by Duke Pallas Negan in Backlund — believing success would make him equal to Nast, King of the Five Seas, turning four Pirate Kings into five — and was foiled when Audrey Hall pierced his disguise. Failing his attempt and fleeing, he was killed by Azik Eggers. His fall rippled on: Creeping Hunger passed to Azik, who sealed its hunger and later bequeathed it to Klein Moretti; his crew and flagship, the Black Death, were subjugated by Tracy, who took his admiralty. After that autumn he survives only as bounty notices, sea rumor, and the glove''s grim afterlife.', null, 5, null, ARRAY['Qilangos', 'Alger Wilson', 'Pallas Negan', 'Audrey Hall', 'Azik Eggers', 'Klein Moretti', 'Tracy'], ARRAY[6], ARRAY['pirate-admiral', 'creeping-hunger', 'twilight-hermit-order', 'assassination', 'sonia-sea', 'spoiler'], 300),
  ('npc-qonas-kilgor', 'Qonas Kilgor — Earl of the Fallen', 'npc', 'Brigadier General Qonas Kilgor is the Deputy Director of MI9, Loen''s supernatural intelligence agency — a burly man in his thirties or forties with a hard black crew-cut, dark blue eyes, a bushy mustache, and abnormally broad shoulders that strain his black suits. His publicly known tastes are simple: Chieftain cigars from East Balam''s Mikent, Texas Hold''em, and autumn hunting in the Backlund suburbs. He shuns banquets and salons, preferring the East Balam Military Veterans Mess. All of it is cover. Kilgor claims to be a Sequence 5 Beyonder, but with the backing of the Augustus royal family he has secretly advanced to Sequence 4 of the Black Emperor pathway — an Earl of the Fallen, a hidden demigod. He is the middleman in dealings between the Demoness Sect and a particular faction of the royal family, an accomplice in the conspiracy behind the Great Smog of Backlund, and the demigod who sacrificed Crazy Captain Connors Viktor and his entire crew to bury evidence of human trafficking. His carefully ordered double life ends when Dwayne Dantès (Klein Moretti), aided by the angel Arianna, turns him into a marionette — extracting confirmation that George Augustus III has cooperated with the Demoness Sect and the Psychology Alchemists and is excavating the Blood Emperor''s remaining mausoleums.', null, 5, null, ARRAY['Qonas Kilgor', 'Klein Moretti', 'Connors Viktor', 'Arianna', 'George Augustus III'], ARRAY[4], ARRAY['mi9', 'black-emperor-pathway', 'demoness-sect', 'augustus-family', 'great-smog', 'spoiler'], 262),
  ('npc-rafter-pound', 'Rafter Pound — The Abject Heir of the Tudors', 'npc', 'Rafter Pound is an abject noble on the verge of bankruptcy — a man in his early forties with light blue eyes and brown hair whitening at the sides, puffy-eyed and deeply wrinkled. His family won a viscountcy for the Battle of the Violated Oath; thirty-two years ago the old Viscount Pound''s two heirs allegedly died of serious illness one after another, and the viscount adopted Rafter, a distant nephew, as heir before dying himself. Rafter lost most of the fortune within eight years and was demoted to baron, then baronet, selling off the family''s Williams Street house along the way. He lives on in Backlund at Unit 29 Sivellaus Street in Empress Borough — beside the capital''s police headquarters — sustaining a life of debaucheries. Beneath the ruin lies a secret: the Pounds descend from the Tudor Family of the Fourth Epoch, the old Williams Street house sits atop an ancient Tudor underground structure where the viscount''s true heirs likely perished, and Rafter himself is a Sequence 9 Lawyer of the Black Emperor pathway. The deathbed charge to "maintain the family" and "remember the glory of the ancestors" consumes him — when rumors of a Black Emperor stir, he becomes convinced the Blood Emperor''s glory will rise again and tunnels back toward the ruins. As a late development he is possessed there by an evil spirit and soon dies during one of his revelries; the authorities afterward destroy Williams Street.', null, 5, 'backlund', ARRAY['Rafter Pound', 'Alista Tudor', 'Millet Carter'], ARRAY[7], ARRAY['tudor-family', 'fallen-noble', 'black-emperor', 'underground-ruins', 'spoiler'], 300),
  ('npc-roselle-gustav', 'Roselle Gustav — The Emperor Who Wrote the Diary', 'npc', 'Roselle Gustav, Emperor of Intis, has been dead since 1198 — assassinated by the Church of the Eternal Blazing Sun, the Church of Steam and Machinery, and the Sauron Family — yet no figure shapes the Fifth Epoch more. Publicly he is the Son of Steam: the genius who drove the steam revolution, overthrew the Intis crown in 1173 to found the Republic, crowned himself Emperor Caesar in 1192, and left behind inventions, literature, playing cards, and proverbs the whole Northern Continent still repeats. The hidden truth: Roselle was a transmigrator from another world, arriving in 1143 into the body of an eighteen-year-old, and his private diary — written in the characters of his homeland, unreadable to any scholar of this world — records everything he learned of Beyonders, pathways, and the hidden orders. Its scattered pages are the most sought-after mystical text alive, hunted by every church and secret society. He climbed the Paragon pathway from Savant, was tutored and later spurned by Zaratul of the Secret Order, joined the Twilight Hermit Order, switched to the Hermit pathway''s Knowledge Emperor, and in his corrupted last years reached for the Black Emperor''s crown itself. His eldest daughter Bernadette and his son Bornova, Trier''s guardian angel, both survive him. Whispers among the highest circles hold that death was not the end of his story.', null, 5, null, ARRAY['Roselle Gustav', 'Bernadette Gustav', 'Bornova Gustav', 'Zaratul'], ARRAY[4], ARRAY['roselle', 'transmigrator', 'intis-republic', 'roselles-diary', 'paragon-pathway', 'spoiler'], 300),
  ('npc-roy', 'Roy — Leader of the Belltaine Veterans', 'npc', 'Roy is a young Loen man, a former soldier, and the leader of a small band of veteran Beyonders — Biles, Phil, and Pasha — who survived the 1350 World War. He fought alongside Biles in the defense of Belltaine City. Roy became a Beyonder entirely by accident: near the war''s end a Sequence 9 Warrior characteristic of the Twilight Giant pathway fused with him, and only luck spared him from losing control on the spot. When he later brushed against other Beyonders and mysticism and learned how lethal that gamble had been, he never dared attempt anything similar again — a caution that marks his leadership. Adrift after the war, the four companions travel to Biles'' hometown of Belltaine seeking survivors, and are swept into the horrors caused by the Sealed Artifact 0-02, the Trunsoest Brass Book, loosed on the city by the former Chief Shepherd Larrion. Roy''s wish to the wandering magician Merlin Hermes is simply to be taken away from Belltaine. After the group helps resolve the incident, Merlin gifts Roy a Pugilist Beyonder characteristic taken from Larrion, and advises that the band can pursue further advancement on the Twilight Giant pathway through the Church of the Fool — a new future, as Roy''s own toast put it.', null, 5, null, ARRAY['Roy', 'Biles', 'Phil', 'Pasha', 'Larrion', 'Klein Moretti'], ARRAY[8], ARRAY['belltaine', 'twilight-giant-pathway', 'war-veteran', 'church-of-the-fool', 'spoiler'], 265),
  ('npc-senor', 'Senor — Admiral of Blood', 'npc', 'Senor, the Admiral of Blood, is one of the seven Pirate Admirals of the southern seas and the head of the Rose School of Thought''s pirate wing — a Sequence 5 Wraith of the Chained pathway, serving under his master Shanks. He looks a man in his forties, pale-faced with deeply recessed sockets, light brown eyes, a double mustache, and an old triangular hat. His reputation is as ugly as his face: cruel, bloodthirsty, and ruled by appetite — his crews kill, loot, and pillage across the sea, and he is said to know a great deal of undead magic. He commands seven or eight ships from his flagship, the Tree of Flesh and Blood, carries a bounty of 42,000 pounds, and owes part of his survival to a Sealed Artifact, the Scales of Luck, which bends fortune his way. He once traded broadsides with the pirate Vice Admiral Dusk, Bulatov Ivan, in the southern waters of Sonia Island, each side losing two ships. In mid-1350 his fleet hunts a fugitive through the waters off Bayam alongside his master, the Sequence 4 Beyonder Shanks, tracking prey by intercepted telegrams — until an interloper reads their signals first. On a mountain outside Bayam, Senor is beaten unconscious by Gehrman Sparrow (Klein Moretti), sucked into the sealed artifact Groselle''s Travels, and made a marionette.', null, 5, null, ARRAY['Senor', 'Shanks', 'Bulatov Ivan', 'Klein Moretti'], ARRAY[7], ARRAY['pirate-admiral', 'chained-pathway', 'rose-school-of-thought', 'sonia-sea', 'spoiler'], 268),
  ('npc-tracy', 'Tracy — Vice Admiral of Ailment', 'npc', 'Tracy, the Vice Admiral of Ailment, is the newest of the Pirate Admirals — after Rear Admiral Hurricane Qilangos died, she subdued his crew by force, proved with action that she had the strength worthy of the rank, and renamed his flagship the Black Death. She is a Sequence 5 Affliction of the Demoness pathway: naturally very beautiful with a heroic vibe, long straight eyebrows, sharp bright-blue eyes, and black hair coiled up high. Tracy is the youngest child of Katarina Pelle, the Demoness Sect''s Saintess of White, and became a Demoness-pathway Beyonder without knowing the potion would make her a woman; she struggled painfully toward her new identity and still likes girls, keeping many maids aboard and treating her lover Helene in the manner of the romance novels she devours. She is an oddity in the Demoness Sect — she has her own ideals and pursuits and no habit of random killing — yet she still works for the organization, including human trafficking traded through Crazy Captain Connors Viktor''s network in the Loen Kingdom. To enemies she is cruel, delighting in destroying the perfection others wish to protect. During the window she prowls the southern sea lanes aboard the Black Death, searching for Helene, holding documents touching the ancient chronicles of Death, and quietly backed by her Saint mother.', null, 5, null, ARRAY['Tracy', 'Katarina Pelle', 'Qilangos', 'Helene', 'Connors Viktor'], ARRAY[6], ARRAY['pirate-admiral', 'demoness-sect', 'black-death', 'sea-lanes', 'spoiler'], 275),
  ('npc-tyre', 'Tyre — Indulgence Faction Werewolf', 'npc', 'Tyre is a Sequence 7 Werewolf of the Chained pathway and a member of the Rose School of Thought''s Indulgence faction — the sect''s crueler current, at war with its own Temperance faction. He is a thin but muscular man whose close-shaved hair stands up in spikes; when he swings his arms, his black fingernails — long as daggers — catch the crimson moonlight with a metallic flash. In the autumn of 1349 Tyre comes to Backlund with his ally Jason under the Wraith Steve, hunting two Temperance-faction fugitives: the mysterious Sharron and her companion Maric. Their method is patient and vicious. They stake out the Bravehearts Bar, the fugitives'' known supply line, and induce a local gang to squeeze the arms dealer Kaspars Kalinin out of his position — bait to force Sharron and Maric into an ambush. Tyre is a capable killer, confident enough to toy with a downed opponent: told to hold off finishing Maric so that Sharron would come to the rescue and Lord Steve could take them both. The trap instead meets counter-preparation — the fugitives have hired outside help — and in the battle that follows Tyre is killed by Sharron herself.', null, 5, null, ARRAY['Tyre', 'Steve', 'Jason', 'Sharron', 'Maric', 'Kaspars Kalinin'], ARRAY[7], ARRAY['rose-school-of-thought', 'chained-pathway', 'werewolf', 'backlund', 'spoiler'], 245),
  ('npc-welch-mcgovern', 'Welch McGovern — The Banker''s Son of Constant', 'npc', 'Welch McGovern is a young man of the Wind City of Constant, the second-largest city of the Loen Kingdom, and the son of a wealthy Constant banker. He studied at Khoy University in Tingen under Senior Associate Professor Cohen, in the same working group as Naya and the original Klein Moretti — and, easy-going, well-funded, and not much troubled by ambition, he fell into the habit of leaning on his cleverer group-mates to carry the work he could not be bothered to do himself. Generous with his father''s money and careless with most else, he is the very picture of the comfortable provincial money that Constant''s coal furnaces and steel mills have made: a chubby, pale-skinned young man, fond of good food and no stranger to a well-set table. To those who knew him he was sociable and open-handed — the kind of heedless, wealthy friend to whom trouble has a way of attaching itself. And attach it did: in the early summer of 1349 Welch was found dead in his Tingen lodgings on Howes Street, his body escorted home to be buried on the coastal outskirts of Constant. His death — reported to the public as a robbery turned to murder — was in truth something far stranger, and it opened one of the hidden world''s darkest doors.', null, 5, 'constant', ARRAY['Welch McGovern', 'Klein Moretti', 'Naya'], '{}', ARRAY['constant', 'khoy-university', 'banking-family', 'civilian'], 225),
  ('npc-will-auceptin', 'Will Auceptin — President of the Life School of Thought', 'npc', 'Will Auceptin is the President of the Life School of Thought and a Beyonder of the Wheel of Fortune pathway at Sequence 1 — a Snake of Mercury. Though "He" appears as a dignified child in "His" early teens — pitch-black-eyed, about 1.4 metres tall, with a missing left calf — "He" is an ancient being who grew and rose to Angel during the Fourth Epoch. "He" is the Angel of Mercury of the Church of the Fool, serving under The Fool (Klein Moretti), and occasionally lends luck to members of the Tarot Club. To evade Ouroboros'' predicted attack, "He" undertook a full restart under the identity "Will Ceres", son of Aaron Ceres, residing at 3 Burningham Road, Hillston Borough, Backlund.', null, 5, 'backlund', ARRAY['Will Auceptin', 'Will Ceres'], ARRAY[1], ARRAY['life-school-of-thought', 'wheel-of-fortune', 'backlund', 'angel', 'church-of-the-fool', 'tarot-club', 'spoiler'], 168),
  ('npc-zaratul', 'Zaratul — The Mad Prophet of the Secret Order', 'npc', 'Zaratul is the leader of the Secret Order, an Angel of the Fool pathway — a Sequence 2 Miracle Invoker who once climbed to Sequence 1 and was broken by it, his soul torn in two by the failed advancement. He appears as an old man in a hooded black robe, white-bearded, his eyes dark as water without light. For years half his sundered soul haunted the Foggy Town hidden in the Hornacis mountain range while the Order he built — heir of the Zaratul Family, hunter of Antigonus Family relics, secretly threaded into the Intis Republic''s intelligence service as Bureau 8 — carried on without him. It was Zaratul who contacted the young Roselle Gustav and traded him Beyonder knowledge for the theft of the Antigonus Family''s Notebook; Roselle''s diary preserves his sayings, including that a miracle is "to be resurrected from the dead." Made whole again in the present day, his madness shed, he moves through Backlund seeking the trail of the Fool — testing fortune-tellers, warning hidden orders, laying patient traps — one of the most dangerous beings walking the Fifth Epoch, and among the very few who know what truly sits above the gray fog is worth fearing.', null, 5, null, ARRAY['Zaratul', 'Roselle Gustav'], ARRAY[4], ARRAY['secret-order', 'fool-pathway', 'angel', 'foggy-town', 'backlund', 'spoiler'], 265),
  ('secret-order-present-day', 'The Secret Order — In the Present Day', 'organization', 'The Secret Order endures into the present as one of the world''s most secretive Beyonder organizations — the Fool-pathway conspiracy the Zaratul Family founded at the close of the War of the Four Emperors. Its goals and philosophy remain unknown even to most of the hidden world; what is known is its hunger for the relics of the destroyed Antigonus Family, and its depth inside the Intis Republic, where it constitutes Bureau 8 of the Republic''s intelligence apparatus. The Order rarely acts openly. Its members surface as collectors, brokers, and quiet inquirers after old notebooks and Fool-pathway antiquities — it once held the Antigonus Family''s Notebook itself, lost it to a careless sale, and dispatched agents as far as Tingen to recover it. Its founder and leader Zaratul vanished long ago into a botched Sequence 1 advancement, and mystical circles now whisper of a reshuffling within the Order''s Intis ranks, as if something long absent had returned to take up the reins.', null, 5, null, ARRAY['Zaratul'], ARRAY[7], ARRAY['secret-order', 'fool-pathway', 'intis-republic', 'bureau-8', 'antigonus-family', 'spoiler'], 235),
  ('death-seq4-undying', 'Death Pathway — Sequence 4: Undying', 'pathway', 'The Undying is the Saint threshold of the Death pathway, the rung where the practitioner stops fearing death by becoming death''s refusal. An Undying possesses Resurrection: unless the body and spirit are completely annihilated, they can gradually revive from lethal injuries, their existence anchored to the River of Eternal Darkness. Their flesh and spirit adopt the Deathless Body, no longer aging, no longer needing food or sleep in any ordinary sense, and highly resistant to diseases, poisons, and mind-affecting powers that target the living. Death Authority deepens their command over undead and spirits, allowing them to bind and command a legion of the dead rather than mere handfuls. The Undying can also mark a target with the Seal of Mortality, hastening decay and making resurrection magic unreliable for the victim. The potion requires two main ingredients — a drop of water from the River of Eternal Darkness and the heart of an Undying King — and three supplementary ingredients: Graveyard Soil from a thousand-year tomb, a wraith''s final breath, and the skull of a Gatekeeper who willingly surrendered their post. The advancement ritual demands dying and returning to life under one''s own power, crossing the threshold of the Underworld and walking back without outside aid. The acting method requires the Undying to treat death as a river to be crossed rather than an enemy to be fought, to shepherd the dead with patience, and to remember that immortality is a responsibility rather than a prize. At Sequence 4 the Death pathway practitioner becomes a fixed point in the cycle of life and death, and the great powers of the Southern Continent take careful note.', 'death', 5, null, '{}', ARRAY[4], ARRAY['death-pathway', 'undying', 'saint-threshold', 'resurrection', 'death-authority'], 290),
  ('death-seq5-gatekeeper', 'Death Pathway — Sequence 5: Gatekeeper', 'pathway', 'The Gatekeeper is the apex of mid-sequence power in the Death pathway, and represents the most dramatic transformation yet: the practitioner does not merely walk the boundary between life and death — they become it. A Gatekeeper gains the Door to the Underworld ability: they can sense the entrance to the Underworld, control the undead within it, and solidify the door as a brand in the palm of their hand. They can summon this door at critical moments to drag targets behind it — a combat ability with no conventional defence. Their most unique power is the Internal Underworld: the Gatekeeper''s own body becomes a cage that houses souls, deceased spirits, and natural spirits within an inner death realm accessible through an entrance at the centre of their brow. This allows a Gatekeeper to carry an entire undead army within themselves, deploying it through the Internal Underworld gate wherever they travel without drawing outward attention. Underworld Sense provides comprehensive awareness of all disturbances across a vast area of the death domain. The potion requires the Skull of an Underworld Wanderer and the Crystal Core of a Myriad-Armed Wraith. The advancement ritual requires opening the Internal Underworld gate within their own body for the first time and housing at least three bound souls within it. The acting method demands guarding the boundary as a sacred responsibility, maintaining order among the dead within the Internal Underworld, and never permitting unauthorized passage through the gate the practitioner now embodies. The Gatekeeper sequence is the point at which the Death pathway practitioner stops being a visitor to the realm of the dead and becomes one of its fundamental institutions.', 'death', 5, null, '{}', ARRAY[5], ARRAY['death-pathway', 'gatekeeper', 'internal-underworld', 'door-to-underworld', 'mid-sequence-apex'], 295)
