-- Capture the issue #213 canon expansion into the repo (prod->repo reconciliation).
-- The 6 remote-only migrations 20260704010619..20260704011343 were applied to
-- prod via MCP but never committed; this consolidates their effect into one
-- idempotent upsert so a fresh DB / branching preview reproduces prod and it is a
-- no-op on prod. Content re-verified against the wiki corpus. 54 rows: 25 new
-- (23 NPC + 2 org), 8 previously-unseeded repo entries, 21 updated dossiers,
-- plus the corrected Death Seq-4/Seq-5 pair (replacing the stale death-seq5-undying).
-- The 6 batch1-owned gods/angels (bladel/cohinem/kotar/olmer/ouroboros/suah) are
-- intentionally excluded (seeded by 20260709130000). narratorOnly is a TS-only
-- flag, not persisted.

on conflict (slug) do update set
  title = excluded.title,
  category = excluded.category,
  content = excluded.content,
  pathway = excluded.pathway,
  epoch = excluded.epoch,
  city = excluded.city,
  npcs = excluded.npcs,
  sequences = excluded.sequences,
  tags = excluded.tags,
  token_count = excluded.token_count;

-- Remove the stale Death Seq-5 slug (repo restructured it to death-seq4-undying +
-- death-seq5-gatekeeper; the corrected pair is upserted above).
delete from public.lore_entries where slug = 'death-seq5-undying';
